{
  "steps": [
    {
      "action": "Inventory the authorized fixture binary: record format, architecture, entrypoints, sections, imports, exports, symbols, strings, protections, and any analysis blockers before deeper reasoning.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": "The analyzed artifact hash matches campaign metadata; binary format and architecture are recorded; expected inventory artifacts exist and parse successfully; missing or malformed inputs are reported as incomplete rather than absence."
    },
    {
      "action": "Map the static call graph around the input surface: identify entrypoints, callers, callees, indirect-call uncertainty, and data-flow-relevant helpers that participate in input handling.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": "Every claimed call edge has an address or symbol locator; unresolved indirect calls are listed explicitly; the call graph identifies which paths are proven and which remain candidates."
    },
    {
      "action": "Trace input acquisition through parsing, transformations, comparisons, branch decisions, success paths, and rejection paths to recover the input-validation logic and document the accepted input representation.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": "The input source and destination representation are identified; every success and rejection branch has a code locator; transformations and comparison constants are supported by decompilation or disassembly evidence; unknown helper behavior is represented as an unresolved dependency."
    },
    {
      "action": "Confirm the recovered static input-validation hypothesis on the authorized fixture using a bounded local debugger or instrumentation probe with explicit readiness, trigger, timeout, and hit requirements.",
      "technique": "RE-BOUNDED-RUNTIME-CONFIRMATION",
      "deterministic_check": "Runtime execution is authorized by campaign scope; the sensor or breakpoint is proven ready before interpreting hits or zero hits; the trigger window and timeout are bounded and recorded; runtime identity is correlated to the same binary hash and module as static evidence."
    }
  ]
}
